// Error type used to mimic uncaught Python exceptions.
// When one of these escapes to the top level, Node prints it to stderr and
// exits with a non-zero status, just like the original Python program does
// when json.loads / jsonschema raise (ValueError, TypeError, re.error, ...).
export class PyError extends Error {
  constructor(kind, message) {
    super(message === undefined ? kind : `${kind}: ${message}`);
    this.kind = kind;
    this.name = 'PyError';
  }
}

