// A JSON number, preserving the distinction Python's json module makes
// between ints and floats (json.loads("2") -> int, json.loads("2.0") -> float).
// `value` is the IEEE-754 double (same as CPython's float parsing),
// `isFloat` mirrors isinstance(x, float), and `big` keeps the exact integer
// value for integer literals (CPython ints have arbitrary precision).
export class JNum {
  constructor(value, isFloat, raw, big) {
    this.value = value;
    this.isFloat = isFloat;
    this.raw = raw;
    this.big = big;
  }
}

export function isJNum(v) {
  return v instanceof JNum;
}

// Numeric view of a JNum (exact BigInt when it is an integer literal that
// lost precision as a double, otherwise the double).
export function numView(n) {
  return n.big !== null ? n.big : n.value;
}

const INT_TOKEN = /^-?(?:0|[1-9][0-9]*)$/;

function makeNumber(token) {
  const isFloat = !INT_TOKEN.test(token);
  const value = Number(token);
  let big = null;
  if (!isFloat) {
    try {
      big = BigInt(token);
    } catch {
      big = null;
    }
  }
  return new JNum(value, isFloat, token, big);
}

// Recursive-descent JSON parser compatible with Python's json.loads:
//  - standard JSON grammar (objects, arrays, strings, numbers, true/false/null)
//  - also accepts NaN, Infinity and -Infinity (Python json allows them)
//  - duplicate object keys: last one wins
//  - combines \uXXXX surrogate pairs like CPython does
export function parseJSON(text) {
  if (typeof text !== 'string') {
    throw new PyError('TypeError', 'the JSON object must be str');
  }
  let pos = 0;
  const len = text.length;

  function err(msg) {
    throw new PyError('ValueError', msg);
  }

  function skipWs() {
    while (pos < len) {
      const c = text.charCodeAt(pos);
      if (c === 0x20 || c === 0x09 || c === 0x0a || c === 0x0d) pos++;
      else break;
    }
  }

  function parseValue() {
    skipWs();
    if (pos >= len) err('Expecting value');
    const c = text[pos];
    if (c === '{') return parseObject();
    if (c === '[') return parseArray();
    if (c === '"') return parseString();
    if (c === 't') return literal('true', true);
    if (c === 'f') return literal('false', false);
    if (c === 'n') return literal('null', null);
    if (c === 'N') return literal('NaN', new JNum(NaN, true, 'NaN', null));
    if (c === 'I') return literal('Infinity', new JNum(Infinity, true, 'Infinity', null));
    if (c === '-' || (c >= '0' && c <= '9')) return parseNumber();
    err('Expecting value');
  }

  function literal(word, value) {
    if (text.startsWith(word, pos)) {
      pos += word.length;
      return value;
    }
    err('Expecting value');
  }

  function parseNumber() {
    const start = pos;
    if (text[pos] === '-') pos++;
    // -Infinity
    if (text.startsWith('Infinity', pos)) {
      pos += 'Infinity'.length;
      return new JNum(-Infinity, true, '-Infinity', null);
    }
    if (pos >= len || text[pos] < '0' || text[pos] > '9') err('Expecting value');
    if (text[pos] === '0') {
      pos++;
    } else {
      while (pos < len && text[pos] >= '0' && text[pos] <= '9') pos++;
    }
    if (text[pos] === '.') {
      pos++;
      if (pos >= len || text[pos] < '0' || text[pos] > '9') err('Expecting value');
      while (pos < len && text[pos] >= '0' && text[pos] <= '9') pos++;
    }
    if (text[pos] === 'e' || text[pos] === 'E') {
      pos++;
      if (text[pos] === '+' || text[pos] === '-') pos++;
      if (pos >= len || text[pos] < '0' || text[pos] > '9') err('Expecting value');
      while (pos < len && text[pos] >= '0' && text[pos] <= '9') pos++;
    }
    return makeNumber(text.slice(start, pos));
  }

  function parseString() {
    pos++; // opening quote
    let out = '';
    while (pos < len) {
      const c = text[pos];
      if (c === '"') {
        pos++;
        return out;
      }
      if (c === '\\') {
        pos++;
        if (pos >= len) break;
        const e = text[pos];
        pos++;
        switch (e) {
          case '"': out += '"'; break;
          case '\\': out += '\\'; break;
          case '/': out += '/'; break;
          case 'b': out += '\b'; break;
          case 'f': out += '\f'; break;
          case 'n': out += '\n'; break;
          case 'r': out += '\r'; break;
          case 't': out += '\t'; break;
          case 'u': {
            const hex = text.slice(pos, pos + 4);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) err('Invalid \\uXXXX escape');
            pos += 4;
            let code = parseInt(hex, 16);
            if (code >= 0xd800 && code <= 0xdbff) {
              // try to combine with a following low-surrogate escape
              if (text[pos] === '\\' && text[pos + 1] === 'u') {
                const hex2 = text.slice(pos + 2, pos + 6);
                if (/^[0-9a-fA-F]{4}$/.test(hex2)) {
                  const lo = parseInt(hex2, 16);
                  if (lo >= 0xdc00 && lo <= 0xdfff) {
                    pos += 6;
                    code = 0x10000 + ((code - 0xd800) << 10) + (lo - 0xdc00);
                    out += String.fromCodePoint(code);
                    break;
                  }
                }
              }
              out += String.fromCharCode(code); // lone surrogate, like Python
            } else {
              out += String.fromCharCode(code);
            }
            break;
          }
          default:
            err('Invalid \\escape');
        }
      } else {
        const cc = text.charCodeAt(pos);
        if (cc < 0x20) err('Invalid control character');
        out += c;
        pos++;
      }
    }
    err('Unterminated string');
  }

  function parseArray() {
    pos++; // [
    const arr = [];
    skipWs();
    if (text[pos] === ']') {
      pos++;
      return arr;
    }
    for (;;) {
      arr.push(parseValue());
      skipWs();
      if (text[pos] === ',') {
        pos++;
        continue;
      }
      if (text[pos] === ']') {
        pos++;
        return arr;
      }
      err("Expecting ',' delimiter");
    }
  }

  function parseObject() {
    pos++; // {
    const obj = {};
    skipWs();
    if (text[pos] === '}') {
      pos++;
      return obj;
    }
    for (;;) {
      skipWs();
      if (text[pos] !== '"') err('Expecting property name enclosed in double quotes');
      const key = parseString();
      skipWs();
      if (text[pos] !== ':') err("Expecting ':' delimiter");
      pos++;
      const value = parseValue();
      obj[key] = value; // last duplicate key wins
      skipWs();
      if (text[pos] === ',') {
        pos++;
        continue;
      }
      if (text[pos] === '}') {
        pos++;
        return obj;
      }
      err("Expecting ',' delimiter");
    }
  }

  const result = parseValue();
  skipWs();
  if (pos !== len) err('Extra data');
  return result;
}

