import { JNum, isJNum, numView } from './jsonparse.mjs';
import { PyError } from './errors.mjs';

// Numeric helpers replicating CPython semantics for the values jsonschema
// compares: ints (arbitrary precision), floats (IEEE doubles) and bools
// (which are ints in Python: True == 1, False == 0).

// Python allows bools anywhere an int is expected in arithmetic/comparison.
function asNumeric(v, what) {
  if (isJNum(v)) return v;
  if (typeof v === 'boolean') {
    return new JNum(v ? 1 : 0, false, v ? '1' : '0', v ? 1n : 0n);
  }
  throw new PyError('TypeError', `'<' not supported with ${what || 'operand'}`);
}

// Three-way comparison matching Python's `<`/`==` between numbers.
// Returns -1, 0, 1, or NaN when either side is a float NaN (in Python all
// comparisons involving float NaN are False, which NaN reproduces in JS when
// the result is used with < / > / <= / >=).
export function compareNums(a, b) {
  a = asNumeric(a, 'left operand');
  b = asNumeric(b, 'right operand');
  const av = numView(a);
  const bv = numView(b);
  if (av < bv) return -1;
  if (av > bv) return 1;
  // eslint-disable-next-line eqeqeq
  if (av == bv) return 0; // == between BigInt and Number is exact
  return NaN;
}

// Equality of two JSON numbers (Python ==): 1 == 1.0 == True, and we treat
// NaN == NaN as true, matching the structural equality jsonschema uses for
// const / enum / uniqueItems.
export function numsEqual(a, b) {
  a = asNumeric(a);
  b = asNumeric(b);
  if (Number.isNaN(a.value) && Number.isNaN(b.value)) return true;
  return compareNums(a, b) === 0;
}

// Compare a plain JS non-negative integer (a len() result) with a keyword
// value, Python-style. Returns -1/0/1 or NaN; throws on str/dict/... just
// like CPython's int < str TypeError.
export function compareLen(n, kw) {
  if (typeof kw === 'boolean') {
    const k = kw ? 1 : 0;
    return n < k ? -1 : n > k ? 1 : 0;
  }
  if (!isJNum(kw)) {
    throw new PyError('TypeError', "'<' not supported between instances of 'int' and other");
  }
  if (kw.big !== null) {
    const bn = BigInt(n);
    return bn < kw.big ? -1 : bn > kw.big ? 1 : 0;
  }
  if (Number.isNaN(kw.value)) return NaN;
  return n < kw.value ? -1 : n > kw.value ? 1 : 0;
}

// Python's float(x) on a huge int raises OverflowError.
export function floatOf(n) {
  if (n.big !== null) {
    const v = Number(n.big);
    if (!Number.isFinite(v)) {
      throw new PyError('OverflowError', 'int too large to convert to float');
    }
    return v;
  }
  return n.value;
}

// multipleOf, replicating jsonschema's keyword:
//   if isinstance(dB, float):
//       quotient = instance / dB
//       try: failed = int(quotient) != quotient
//       except OverflowError: failed = True
//   else:
//       failed = instance % dB
export function isMultiple(instance, dB) {
  if (!isJNum(dB) && typeof dB !== 'boolean') {
    throw new PyError('TypeError', 'unsupported operand type(s) for % or /');
  }
  if (typeof dB === 'boolean') {
    dB = new JNum(dB ? 1 : 0, false, dB ? '1' : '0', dB ? 1n : 0n);
  }
  if (dB.isFloat) {
    if (dB.value === 0) {
      // Python raises ZeroDivisionError on float division by zero.
      throw new PyError('ZeroDivisionError', 'float division by zero');
    }
    const quotient = floatOf(instance) / dB.value;
    if (Number.isNaN(quotient)) {
      // int(float('nan')) raises ValueError in CPython.
      throw new PyError('ValueError', 'cannot convert float NaN to integer');
    }
    if (!Number.isFinite(quotient)) return false; // OverflowError -> failed
    return Math.trunc(quotient) === quotient;
  }
  // integer divisor path: Python's instance % dB (truthiness of the remainder)
  if ((dB.big !== null && dB.big === 0n) || (dB.big === null && dB.value === 0)) {
    throw new PyError('ZeroDivisionError', 'integer division or modulo by zero');
  }
  if (instance.big !== null && dB.big !== null) {
    return instance.big % dB.big === 0n; // exact integer modulo
  }
  const divisor = dB.big !== null ? Number(dB.big) : dB.value;
  const remainder = numViewAsNumber(instance) % divisor;
  return remainder === 0; // NaN remainder is truthy in Python -> failed
}

function numViewAsNumber(n) {
  return n.big !== null ? Number(n.big) : n.value;
}

// jsonschema / Python type checks on parsed JSON values.
export function isObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v) && !isJNum(v);
}

export function isType(instance, type) {
  switch (type) {
    case 'null':
      return instance === null;
    case 'boolean':
      return typeof instance === 'boolean';
    case 'object':
      return isObject(instance);
    case 'array':
      return Array.isArray(instance);
    case 'number':
      return isJNum(instance);
    case 'integer':
      // bool is excluded; integral floats (1.0) count, NaN/Infinity do not
      return isJNum(instance) && (!instance.isFloat || Number.isInteger(instance.value));
    case 'string':
      return typeof instance === 'string';
    default:
      // jsonschema raises UnknownType for an unknown type name.
      throw new PyError('UnknownType', `${String(type)} is unknown to this type checker`);
  }
}

