import { isJNum } from './jsonparse.mjs';
import { numsEqual, isObject } from './numbers.mjs';

// Structural equality matching the semantics the jsonschema library applies
// for `const`, `enum` and `uniqueItems`:
//  - numbers compare by value across int/float (1 == 1.0)
//  - booleans are never equal to numbers (True is distinct from 1)
//  - NaN is considered equal to NaN
//  - arrays/objects compare element-wise (object key order irrelevant)
export function jsonEqual(a, b) {
  if (a === b) return true; // same reference, primitives, null, strings
  const aNum = isJNum(a);
  const bNum = isJNum(b);
  if (aNum || bNum) {
    if (!(aNum && bNum)) {
      // number vs bool is unequal (bools are distinct); number vs anything
      // else is unequal in Python as well (1 == '1' is False, 1 == [] False)
      return false;
    }
    return numsEqual(a, b);
  }
  if (typeof a === 'boolean' || typeof b === 'boolean') return false;
  if (a === null || b === null) return false;
  if (typeof a === 'string' || typeof b === 'string') return false;
  const aArr = Array.isArray(a);
  const bArr = Array.isArray(b);
  if (aArr || bArr) {
    if (!(aArr && bArr) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!jsonEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (isObject(a) && isObject(b)) {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    for (const k of ka) {
      if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
      if (!jsonEqual(a[k], b[k])) return false;
    }
    return true;
  }
  return false;
}

// uniqueItems: pairwise structural equality.
export function allUnique(container) {
  for (let i = 0; i < container.length; i++) {
    for (let j = i + 1; j < container.length; j++) {
      if (jsonEqual(container[i], container[j])) return false;
    }
  }
  return true;
}

