import { isObject } from './numbers.mjs';
import { PyError } from './errors.mjs';

// Local $ref resolution against the root document, mirroring what
// jsonschema's RefResolver does for fragment-only references in draft-07:
//   "" / "#"          -> the whole document
//   "#/a/b"           -> JSON pointer (with ~0 / ~1 unescaping)
// Anything else (remote URLs, plain-name fragments, dangling pointers) makes
// the Python program die with an exception, so we raise.
export function resolveRef(root, ref) {
  if (typeof ref !== 'string') {
    throw new PyError('RefResolutionError', 'non-string $ref value');
  }
  if (ref === '' || ref === '#') {
    return root;
  }
  if (!ref.startsWith('#')) {
    // Remote references would be fetched over the network by jsonschema.
    throw new PyError('RefResolutionError', `Unresolvable JSON pointer: ${ref}`);
  }
  const fragment = ref.slice(1);
  if (!fragment.startsWith('/')) {
    throw new PyError('RefResolutionError', `Unresolvable JSON pointer: ${fragment}`);
  }
  let current = root;
  for (const rawPart of fragment.slice(1).split('/')) {
    const part = rawPart.replace(/~1/g, '/').replace(/~0/g, '~');
    if (Array.isArray(current)) {
      const trimmed = part.trim();
      if (!/^[+-]?\d+$/.test(trimmed)) {
        throw new PyError('RefResolutionError', `Unresolvable JSON pointer: ${fragment}`);
      }
      let idx = parseInt(trimmed, 10);
      if (idx < 0) idx = current.length + idx; // Python list negative indexing
      if (idx < 0 || idx >= current.length) {
        throw new PyError('RefResolutionError', `Unresolvable JSON pointer: ${fragment}`);
      }
      current = current[idx];
    } else if (isObject(current)) {
      if (!Object.prototype.hasOwnProperty.call(current, part)) {
        throw new PyError('RefResolutionError', `Unresolvable JSON pointer: ${fragment}`);
      }
      current = current[part];
    } else {
      throw new PyError('RefResolutionError', `Unresolvable JSON pointer: ${fragment}`);
    }
  }
  return current;
}

