import { JNum, isJNum } from './jsonparse.mjs';
import { PyError } from './errors.mjs';
import {
  compareNums,
  compareLen,
  isMultiple,
  isObject,
  isType,
} from './numbers.mjs';
import { jsonEqual, allUnique } from './equality.mjs';
import { resolveRef } from './resolver.mjs';

// A validation error marker. Only the *number* of yielded errors matters for
// this program's output, so a shared sentinel per keyword is sufficient.
function err(keyword) {
  return { keyword };
}

function strLen(s) {
  // Python len() counts Unicode code points.
  return [...s].length;
}

function* errors(validator, instance, schema) {
  yield* validator.iterErrors(instance, schema);
}

export function* ref(validator, refValue, instance) {
  const resolved = resolveRef(validator.schema, refValue);
  yield* errors(validator, instance, resolved);
}

export function* type(validator, types, instance) {
  const list = Array.isArray(types) ? types : [types];
  for (const t of list) {
    if (isType(instance, t)) return;
  }
  yield err('type');
}

export function* enum_(validator, enums, instance) {
  for (const each of enums) {
    if (jsonEqual(each, instance)) return;
  }
  yield err('enum');
}

export function* const_(validator, constValue, instance) {
  if (!jsonEqual(constValue, instance)) {
    yield err('const');
  }
}

export function* multipleOf(validator, dB, instance) {
  if (!isType(instance, 'number')) return;
  if (!isMultiple(instance, dB)) {
    yield err('multipleOf');
  }
}

export function* minimum(validator, minimum, instance) {
  if (!isType(instance, 'number')) return;
  if (compareNums(instance, minimum) < 0) yield err('minimum');
}

export function* maximum(validator, maximum, instance) {
  if (!isType(instance, 'number')) return;
  if (compareNums(instance, maximum) > 0) yield err('maximum');
}

export function* exclusiveMinimum(validator, minimum, instance) {
  if (!isType(instance, 'number')) return;
  if (compareNums(instance, minimum) <= 0) yield err('exclusiveMinimum');
}

export function* exclusiveMaximum(validator, maximum, instance) {
  if (!isType(instance, 'number')) return;
  if (compareNums(instance, maximum) >= 0) yield err('exclusiveMaximum');
}

export function* minLength(validator, mL, instance) {
  if (!isType(instance, 'string')) return;
  if (compareLen(strLen(instance), mL) < 0) yield err('minLength');
}

export function* maxLength(validator, mL, instance) {
  if (!isType(instance, 'string')) return;
  if (compareLen(strLen(instance), mL) > 0) yield err('maxLength');
}

function pyRegExp(pattern) {
  if (typeof pattern !== 'string') {
    throw new PyError('TypeError', 'first argument must be string or compiled pattern');
  }
  try {
    return new RegExp(pattern);
  } catch (e) {
    throw new PyError('re.error', e.message);
  }
}

export function* pattern(validator, patternValue, instance) {
  if (!isType(instance, 'string')) return;
  if (!pyRegExp(patternValue).test(instance)) yield err('pattern');
}

export function* items(validator, itemsValue, instance) {
  if (!isType(instance, 'array')) return;
  if (isObject(itemsValue) || typeof itemsValue === 'boolean') {
    for (const item of instance) {
      yield* errors(validator, item, itemsValue);
    }
    return;
  }
  if (!Array.isArray(itemsValue)) {
    // zip(enumerate(instance), <non-iterable>) raises in Python as soon as
    // the instance is non-empty.
    if (instance.length > 0) {
      throw new PyError('TypeError', 'object is not iterable');
    }
    return;
  }
  const n = Math.min(instance.length, itemsValue.length);
  for (let i = 0; i < n; i++) {
    yield* errors(validator, instance[i], itemsValue[i]);
  }
}

export function* additionalItems(validator, aI, instance, schema) {
  if (!isType(instance, 'array')) return;
  const itemsValue = Object.prototype.hasOwnProperty.call(schema, 'items')
    ? schema.items
    : {};
  if (isObject(itemsValue) || typeof itemsValue === 'boolean') return;
  if (!Array.isArray(itemsValue)) return;
  const lenItems = itemsValue.length;
  if (isObject(aI)) {
    for (let i = lenItems; i < instance.length; i++) {
      yield* errors(validator, instance[i], aI);
    }
  } else if (!truthy(aI) && instance.length > lenItems) {
    yield err('additionalItems');
  }
}

function truthy(v) {
  // Python truthiness for JSON values: false/null/0/""/[]/{} are falsy.
  if (v === null || v === false || v === undefined) return false;
  if (v === true) return true;
  if (isJNum(v)) return v.value !== 0 && !Number.isNaN(v.value);
  if (typeof v === 'string') return v.length > 0;
  if (Array.isArray(v)) return v.length > 0;
  if (isObject(v)) return Object.keys(v).length > 0;
  return Boolean(v);
}

export function* contains(validator, containsValue, instance) {
  if (!isType(instance, 'array')) return;
  for (const element of instance) {
    if (validator.isValidAgainst(element, containsValue)) return;
  }
  yield err('contains');
}

export function* minItems(validator, mI, instance) {
  if (!isType(instance, 'array')) return;
  if (compareLen(instance.length, mI) < 0) yield err('minItems');
}

export function* maxItems(validator, mI, instance) {
  if (!isType(instance, 'array')) return;
  if (compareLen(instance.length, mI) > 0) yield err('maxItems');
}

export function* uniqueItems(validator, uI, instance) {
  if (!truthy(uI) || !isType(instance, 'array')) return;
  if (!allUnique(instance)) yield err('uniqueItems');
}

export function* minProperties(validator, mP, instance) {
  if (!isType(instance, 'object')) return;
  if (compareLen(Object.keys(instance).length, mP) < 0) yield err('minProperties');
}

export function* maxProperties(validator, mP, instance) {
  if (!isType(instance, 'object')) return;
  if (compareLen(Object.keys(instance).length, mP) > 0) yield err('maxProperties');
}

export function* required(validator, requiredValue, instance) {
  if (!isType(instance, 'object')) return;
  if (typeof requiredValue === 'string') {
    // Python iterates a string char by char.
    for (const property of requiredValue) {
      if (!Object.prototype.hasOwnProperty.call(instance, property)) {
        yield err('required');
      }
    }
    return;
  }
  for (const property of requiredValue) {
    if (typeof property === 'string') {
      if (!Object.prototype.hasOwnProperty.call(instance, property)) {
        yield err('required');
      }
    } else if (!containsKey(instance, property)) {
      yield err('required');
    }
  }
}

function containsKey(obj, key) {
  // `property in instance` with a non-string key raises in Python for dicts
  // (unhashable types) or is False; keep it simple: only strings can be keys.
  return typeof key === 'string' && Object.prototype.hasOwnProperty.call(obj, key);
}

export function* properties(validator, propertiesValue, instance) {
  if (!isType(instance, 'object')) return;
  if (!isObject(propertiesValue)) {
    throw new PyError('AttributeError', 'object has no attribute items');
  }
  for (const [property, subschema] of Object.entries(propertiesValue)) {
    if (Object.prototype.hasOwnProperty.call(instance, property)) {
      yield* errors(validator, instance[property], subschema);
    }
  }
}

export function* patternProperties(validator, patternPropertiesValue, instance) {
  if (!isType(instance, 'object')) return;
  if (!isObject(patternPropertiesValue)) {
    throw new PyError('AttributeError', 'object has no attribute items');
  }
  for (const [pat, subschema] of Object.entries(patternPropertiesValue)) {
    const re = pyRegExp(pat);
    for (const [k, v] of Object.entries(instance)) {
      if (re.test(k)) {
        yield* errors(validator, v, subschema);
      }
    }
  }
}

export function* additionalProperties(validator, aP, instance, schema) {
  if (!isType(instance, 'object')) return;
  const props = isObject(schema.properties) ? schema.properties : {};
  let patterns = null;
  if (isObject(schema.patternProperties)) {
    const keys = Object.keys(schema.patternProperties);
    if (keys.length > 0) patterns = pyRegExp(keys.join('|'));
  }
  const extras = [];
  for (const property of Object.keys(instance)) {
    if (Object.prototype.hasOwnProperty.call(props, property)) continue;
    if (patterns && patterns.test(property)) continue;
    extras.push(property);
  }
  if (isObject(aP)) {
    for (const extra of extras) {
      yield* errors(validator, instance[extra], aP);
    }
  } else if (aP === false && extras.length > 0) {
    yield err('additionalProperties');
  }
}

export function* dependencies(validator, dependenciesValue, instance) {
  if (!isType(instance, 'object')) return;
  if (!isObject(dependenciesValue)) {
    throw new PyError('AttributeError', 'object has no attribute items');
  }
  for (const [property, dependency] of Object.entries(dependenciesValue)) {
    if (!Object.prototype.hasOwnProperty.call(instance, property)) continue;
    if (Array.isArray(dependency)) {
      for (const each of dependency) {
        if (typeof each !== 'string' || !Object.prototype.hasOwnProperty.call(instance, each)) {
          yield err('dependencies');
        }
      }
    } else {
      yield* errors(validator, instance, dependency);
    }
  }
}

export function* propertyNames(validator, propertyNamesValue, instance) {
  if (!isType(instance, 'object')) return;
  for (const property of Object.keys(instance)) {
    yield* errors(validator, property, propertyNamesValue);
  }
}

export function* if_(validator, ifSchema, instance, schema) {
  if (validator.isValidAgainst(instance, ifSchema)) {
    if (Object.prototype.hasOwnProperty.call(schema, 'then')) {
      yield* errors(validator, instance, schema.then);
    }
  } else if (Object.prototype.hasOwnProperty.call(schema, 'else')) {
    yield* errors(validator, instance, schema.else);
  }
}

export function* allOf(validator, allOfValue, instance) {
  for (const subschema of allOfValue) {
    yield* errors(validator, instance, subschema);
  }
}

export function* anyOf(validator, anyOfValue, instance) {
  for (const subschema of anyOfValue) {
    if (validator.isValidAgainst(instance, subschema)) return;
  }
  yield err('anyOf');
}

export function* oneOf(validator, oneOfValue, instance) {
  let validCount = 0;
  for (const subschema of oneOfValue) {
    if (validator.isValidAgainst(instance, subschema)) validCount++;
  }
  if (validCount !== 1) {
    yield err('oneOf');
  }
}

export function* not_(validator, notSchema, instance) {
  if (validator.isValidAgainst(instance, notSchema)) {
    yield err('not');
  }
}

