import { isObject } from './numbers.mjs';
import { PyError } from './errors.mjs';
import * as kw from './keywords.mjs';

// Keyword validators for draft-07, in the spirit of jsonschema's
// Draft7Validator.VALIDATORS. `format` is intentionally absent: without a
// format checker it never produces errors.
const VALIDATORS = {
  $ref: kw.ref,
  type: kw.type,
  enum: kw.enum_,
  const: kw.const_,
  multipleOf: kw.multipleOf,
  maximum: kw.maximum,
  exclusiveMaximum: kw.exclusiveMaximum,
  minimum: kw.minimum,
  exclusiveMinimum: kw.exclusiveMinimum,
  maxLength: kw.maxLength,
  minLength: kw.minLength,
  pattern: kw.pattern,
  items: kw.items,
  additionalItems: kw.additionalItems,
  contains: kw.contains,
  maxItems: kw.maxItems,
  minItems: kw.minItems,
  uniqueItems: kw.uniqueItems,
  maxProperties: kw.maxProperties,
  minProperties: kw.minProperties,
  required: kw.required,
  properties: kw.properties,
  patternProperties: kw.patternProperties,
  additionalProperties: kw.additionalProperties,
  dependencies: kw.dependencies,
  propertyNames: kw.propertyNames,
  if: kw.if_,
  allOf: kw.allOf,
  anyOf: kw.anyOf,
  oneOf: kw.oneOf,
  not: kw.not_,
};

export class Draft7Validator {
  constructor(schema) {
    this.schema = schema;
  }

  // Mirrors jsonschema's Validator.iter_errors: boolean schemas short
  // circuit, a `$ref` key makes all sibling keywords be ignored (draft-07
  // semantics as implemented by jsonschema), otherwise every keyword present
  // in the schema that has a registered validator is applied.
  *iterErrors(instance, schema = this.schema) {
    if (schema === true) return;
    if (schema === false) {
      yield { keyword: 'false schema' };
      return;
    }
    if (!isObject(schema)) {
      // Python would fail calling schema.items().
      throw new PyError('AttributeError', 'schema has no attribute items');
    }
    if (Object.prototype.hasOwnProperty.call(schema, '$ref')) {
      yield* kw.ref(this, schema.$ref, instance, schema);
      return;
    }
    for (const [k, v] of Object.entries(schema)) {
      const fn = VALIDATORS[k];
      if (fn === undefined) continue;
      yield* fn(this, v, instance, schema);
    }
  }

  *descend(instance, schema) {
    yield* this.iterErrors(instance, schema);
  }

  // Equivalent of validator.evolve(schema=subschema).is_valid(instance).
  isValidAgainst(instance, schema) {
    for (const _ of this.iterErrors(instance, schema)) {
      return false;
    }
    return true;
  }
}

