import { basename } from 'node:path';

// A minimal re-implementation of the Python argparse behavior used by the
// original script:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
// Supports `--a value`, `--a=value`, unambiguous long-option prefixes, `-h`,
// negative-number values, argparse's error messages and exit codes.

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv) {
  const prog = basename(argv[1] || 'test5.mjs');
  const usage = `usage: ${prog} [-h] --a A --b B`;
  const argvRest = argv.slice(2);

  const error = (message) => {
    process.stderr.write(`${usage}\n${prog}: error: ${message}\n`);
    process.exit(2);
  };
  const printHelp = () => {
    process.stdout.write(
      `${usage}\n\n` +
        'options:\n' +
        '  -h, --help  show this help message and exit\n' +
        '  --a A       instance (JSON string)\n' +
        '  --b B       schema (JSON string)\n',
    );
    process.exit(0);
  };

  const values = {};
  const seen = new Set();
  const extras = [];
  let noMoreOptions = false;

  for (let i = 0; i < argvRest.length; i++) {
    const token = argvRest[i];
    if (!noMoreOptions && token === '--') {
      noMoreOptions = true;
      continue;
    }
    if (!noMoreOptions && token.startsWith('--')) {
      let name = token.slice(2);
      let inlineValue = null;
      const eq = name.indexOf('=');
      if (eq !== -1) {
        inlineValue = name.slice(eq + 1);
        name = name.slice(0, eq);
      }
      // argparse allows unambiguous abbreviations of long options.
      const candidates = ['help', 'a', 'b'].filter((o) => o.startsWith(name));
      if (name === '' || candidates.length === 0) {
        extras.push(token);
        continue;
      }
      if (candidates.length > 1 && !candidates.includes(name)) {
        error(`ambiguous option: --${name} could match ${candidates.map((c) => '--' + c).join(', ')}`);
      }
      const option = candidates.includes(name) ? name : candidates[0];
      if (option === 'help') {
        printHelp();
      }
      let value = inlineValue;
      if (value === null) {
        const next = argvRest[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          error(`argument --${option}: expected one argument`);
        }
        value = next;
        i++;
      }
      values[option] = value;
      seen.add(option);
      continue;
    }
    if (!noMoreOptions && looksLikeOption(token)) {
      // short options: only -h exists; it exits immediately
      if (token[1] === 'h') {
        printHelp();
      }
      extras.push(token);
      continue;
    }
    extras.push(token);
  }

  const missing = ['a', 'b'].filter((o) => !seen.has(o));
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.map((m) => '--' + m).join(', ')}`);
  }
  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

